const unit=(role,text)=>({role,text});
const grouped=(items)=>items.flatMap(([title,copy])=>[unit('subheading',title),unit('paragraph',copy)]);

export function finalSourceSection(page,section){
 const d=serviceCopy[page.index];if(!d&&!(page.type==='location'&&section.index===5))return section;
 let items,eye;
 if(section.index===2){items=d.problems;eye='The problem, and a better way to use the space';}
 if(section.index===3){items=d.choices;eye=page.index===1?'Residential Services':page.index===8?'Commercial Services':'Film Services';}
 if(section.index===4){
  const business=page.index>=8;
  items=[
   ['39+ years of industry experience','Bill started the business in 1987. His window-film experience helps us explain your options and the work involved before you decide.'],
   ['Advice around your priorities','We consider your glass and the way you use the space. The film should address the problem you actually want to solve.'],
   ['A finish you can understand','Compare suitable samples, colour and reflection. Understand the product’s benefits and limits before agreeing to the work.'],
   ['Care with the fitting',business?'We discuss access, opening hours and preparation, with a fitting plan that is clear to the people using your building.':'We discuss access and preparation around your home, including which areas need to be clear for fitting.'],
   ['Product and warranty guidance','Ask who provides the selected product’s warranty, what it covers and its conditions. Terms depend on the film and application.'],
   ['Help after installation','Keep the drying and cleaning guidance. Contact us about persistent bubbles, lifting edges or another concern.']
  ];eye='Why Choose Us';
 }
 if(section.index===5){items=[
  ['1. Tell us what needs to improve','Share your location, photographs and main concern. Tell us when the problem occurs and what you want to preserve.'],
  ['2. Check the glass and access','We consider the glass, coatings and exposure, then confirm whether more information or a site assessment is needed.'],
  ['3. Compare suitable films','Review suitable samples, performance information and limitations. Choose around the room, the finish and the benefit you need.'],
  ['4. Agree your quote and plan','Confirm the film, panes, price, access, timing and any required approvals. The agreed work should be clear before fitting.'],
  ['5. Installation and care','The glass is prepared and film fitted. Follow the selected product’s care instructions and contact us if you need help.']
 ];eye='How It Works';}
 if(section.index===7){items=d.faqs;eye='Common Questions';}
 if(!items)return section;
 return {...section,units:[unit('eyebrow',eye),...section.units.filter(u=>u.role==='heading'),...grouped(items)]};
}

export function finalBrief(page,original){
 const d=serviceCopy[page.index];
 if(d)return {...original,paras:d.intro,end:d.end};
 const local=localBriefs[page.index];
 if(local)return {...original,paras:local.intro,end:local.end,endTitle:local.next};
 return otherBriefs[page.index]?{...original,...otherBriefs[page.index]}:original;
}

